const API = (import.meta.env.VITE_API_URL || '').replace(/\/$/, '');

/** Bound HTTP requests so an unreachable market-data provider cannot leave the UI busy forever. */
async function apiFetch(input: RequestInfo | URL, init?: RequestInit, timeoutMs = 15000): Promise<Response> {
 const controller = new AbortController();
 const timer = window.setTimeout(() => controller.abort(), timeoutMs);
 try {
  return await fetch(input, { ...init, signal: controller.signal });
 } catch (error) {
  if (error instanceof DOMException && error.name === 'AbortError') {
   throw new Error(`Request timed out after ${Math.round(timeoutMs / 1000)} seconds. Check the API or data provider and try again.`);
  }
  if (error instanceof TypeError) {
   throw new Error('Cannot reach the BharatStock API. Check that the backend is running and the API URL is correct.');
  }
  throw error;
 } finally {
  window.clearTimeout(timer);
 }
}
