function parseMarketTimestamp(value:unknown):Date {
 // Providers can omit timestamps or return null for partial bars. Never call string
 // methods on untrusted API data; invalid values should be handled as unavailable.
 if(typeof value !== 'string' || !value.trim()) return new Date(Number.NaN);
 // Provider daily/weekly/monthly bars may be date-only. Parse those as calendar dates
 // instead of JavaScript's UTC interpretation, which can shift the displayed day in IST.
 const match=value.match(/^(\d{4})-(\d{2})-(\d{2})$/);
 if(match) return new Date(`${match[1]}-${match[2]}-${match[3]}T12:00:00+05:30`);
 return new Date(value);
}
function formatMarketTimestamp(value:unknown, interval:string, includeTime=true):string {
 const d=parseMarketTimestamp(value); if(Number.isNaN(d.getTime())) return 'Timestamp unavailable';
 const date=new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',day:'2-digit',month:'short',year:interval==='5m'||interval==='10m'||interval==='15m'||interval==='30m'||interval==='1h'||interval==='4h'?undefined:'numeric'}).format(d);
 const intraday=['5m','10m','15m','30m','1h','4h'].includes(interval);
 if(!includeTime||!intraday) return date;
 return `${date}, ${new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',hour12:true}).format(d)}`;
}
function getIndianSessionStatus(now:number):{isRegularHours:boolean;label:string;detail:string} {
 const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kolkata',weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(now));
 const get=(type:string)=>parts.find(part=>part.type===type)?.value||'';
 const weekday=get('weekday'); const minuteOfDay=Number(get('hour'))*60+Number(get('minute'));
 const weekdaySession=!['Sat','Sun'].includes(weekday); const isRegularHours=weekdaySession&&minuteOfDay>=9*60+15&&minuteOfDay<15*60+30;
 return isRegularHours?{isRegularHours:true,label:'Regular session hours',detail:'09:15–15:30 IST; exchange holidays may differ'}:{isRegularHours:false,label:'Market closed · outside regular hours',detail:'Regular NSE/BSE session is generally 09:15–15:30 IST on weekdays; holidays are not inferred'};
}
type IntradayTick = { time: string; timestamp: number; price: number };

function LiveIntradayChart({ ticks, theme }: { ticks: IntradayTick[]; theme: 'dark' | 'light' }) {
  const valid = ticks.filter(t => Number.isFinite(t.timestamp) && Number.isFinite(t.price) && t.price > 0).sort((a,b) => a.timestamp-b.timestamp);
  if (valid.length < 2) return <div className="empty chartEmpty" role="status"><Activity size={30}/><b>Waiting for fresh live observations</b><span>At least two valid observations from the live feed are needed. No historical candles or artificial ticks are substituted.</span></div>;
  const W=1100,H=420,left=85,right=25,top=35,bottom=345;
  const prices=valid.map(t=>t.price), min=Math.min(...prices), max=Math.max(...prices);
  const pad=Math.max((max-min)*.12,Math.abs(max)*.0005,.01), low=min-pad, high=max+pad;
  const x=(i:number)=>left+(i/Math.max(1,valid.length-1))*(W-left-right);
  const y=(v:number)=>top+((high-v)/(high-low))*(bottom-top);
  const path=valid.map((t,i)=>`${i===0?'M':'L'} ${x(i).toFixed(2)} ${y(t.price).toFixed(2)}`).join(' ');
  const colors={grid:theme==='light'?'#e2e8f0':'#263449',text:theme==='light'?'#64748b':'#8ea0b8',line:'#22c55e'};
  const first=valid[0], latest=valid[valid.length-1], change=latest.price-first.price, pct=first.price?change/first.price*100:0;
  const time=(v:number)=>new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(v));
  return <div className="tradingChartWrap"><div className="ohlcStrip"><span>First <b>{first.price.toLocaleString('en-IN',{maximumFractionDigits:2})}</b></span><span>Latest <b>{latest.price.toLocaleString('en-IN',{maximumFractionDigits:2})}</b></span><span className={change>=0?'positive':'negative'}>Change <b>{pct>=0?'+':''}{pct.toFixed(3)}%</b></span><span className="ohlcTime">{time(latest.timestamp)}</span></div><svg className="tradingSvg" viewBox={`0 0 ${W} ${H}`} role="img" aria-label="Live quote observation line chart, not OHLC candles">{Array.from({length:6},(_,i)=>{const price=high-(high-low)*i/5,yy=y(price);return <g key={i}><line x1={left} x2={W-right} y1={yy} y2={yy} stroke={colors.grid} strokeDasharray="3 5"/><text x={left-10} y={yy+4} textAnchor="end" fill={colors.text} fontSize="12">{price.toLocaleString('en-IN',{maximumFractionDigits:2})}</text></g>})}<path d={path} fill="none" stroke={colors.line} strokeWidth="2.5" strokeLinejoin="round" strokeLinecap="round" vectorEffect="non-scaling-stroke"/>{valid.map((t,i)=><circle key={`${t.timestamp}-${i}`} cx={x(i)} cy={y(t.price)} r={valid.length>60?2:3.5} fill={colors.line}/>)}<text x={left} y={H-20} fill={colors.text} fontSize="12">{time(first.timestamp)}</text><text x={W-right} y={H-20} textAnchor="end" fill={colors.text} fontSize="12">{time(latest.timestamp)}</text></svg><div className="chartLegend"><span><i style={{background:colors.line}}/> Live quote observations</span><small>{valid.length} observations · This is not a reconstructed OHLC candle chart or exchange trade tape.</small></div></div>;
}

function TradingChart({bars,theme,loading,error,interval,indicators,visibleBars,chartType}:{bars:Candle[];theme:'dark'|'light';loading:boolean;error:string;interval:string;indicators:string[];visibleBars:number;chartType:'candles'|'line'}) {
 const [hover,setHover]=useState<number|null>(null);
 const W=1100,H=420,left=76,right=24,top=28,priceBottom=306,volBottom=378;
 const validAll=bars.filter(b=>typeof b.time==='string' && b.time.trim().length>0 && !Number.isNaN(parseMarketTimestamp(b.time).getTime()) && [b.Open,b.High,b.Low,b.Close].every(v=>Number.isFinite(Number(v))));
 const valid=visibleBars>=validAll.length?validAll:validAll.slice(-visibleBars);
 const moving=(period:number,kind:'sma'|'ema'='sma')=>valid.map((b,i)=>{if(i+1<period)return null;if(kind==='ema'){const alpha=2/(period+1);let value=valid[0].Close;for(let j=1;j<=i;j++)value=valid[j].Close*alpha+value*(1-alpha);return value;}return valid.slice(i-period+1,i+1).reduce((sum,item)=>sum+item.Close,0)/period;});
 const sma20=moving(20),sma50=moving(50),ema20=moving(20,'ema');
 const bb=valid.map((b,i)=>{if(i<19)return null;const sample=valid.slice(i-19,i+1).map(item=>item.Close),mean=sample.reduce((a,v)=>a+v,0)/20,sd=Math.sqrt(sample.reduce((a,v)=>a+(v-mean)**2,0)/20);return {upper:mean+2*sd,lower:mean-2*sd};});
 if(loading)return <div className="chartLoading" role="status">Loading real OHLC bars from the market-data provider…</div>;
 if(error||!valid.length)return <div className="empty chartEmpty"><Activity size={30}/><b>{error?'Chart data unavailable':'No OHLC bars available'}</b><span>{error||'Try another interval or symbol. No sample candles are generated.'}</span></div>;
 const min=Math.min(...valid.map(b=>b.Low)),max=Math.max(...valid.map(b=>b.High)),pad=(max-min)*.06||1,lo=min-pad,hi=max+pad;
 const x=(i:number)=>left+(i+.5)*(W-left-right)/valid.length; const y=(v:number)=>top+(hi-v)/(hi-lo)*(priceBottom-top); const volumeAvailable=valid.some(b=>b.Volume!=null&&Number(b.Volume)>0); const volMax=Math.max(1,...valid.map(b=>Number(b.Volume)||0)); const step=(W-left-right)/valid.length; const bodyW=Math.max(2,Math.min(12,step*.62)); const colors={grid:theme==='light'?'#e2e8f0':'#263449',text:theme==='light'?'#64748b':'#8ea0b8',green:'#16a879',red:'#e45c70',blue:'#60a5fa',gold:'#f59e0b'}; const current=valid[hover??valid.length-1];
 const pathFor=(values:(number|null)[])=>values.map((v,i)=>v==null?'':`${i===0||values.slice(0,i).every(x=>x==null)?'M':'L'} ${x(i).toFixed(2)} ${y(v).toFixed(2)}`).filter(Boolean).join(' ');
 const closePath=pathFor(valid.map(b=>b.Close));
 const label=(t:string)=>formatMarketTimestamp(t,interval);
 return <div className="tradingChartWrap"><div className="ohlcStrip"><span>O <b>{current.Open.toLocaleString('en-IN',{maximumFractionDigits:2})}</b></span><span>H <b>{current.High.toLocaleString('en-IN',{maximumFractionDigits:2})}</b></span><span>L <b>{current.Low.toLocaleString('en-IN',{maximumFractionDigits:2})}</b></span><span className={current.Close>=current.Open?'positive':'negative'}>C <b>{current.Close.toLocaleString('en-IN',{maximumFractionDigits:2})}</b></span><span>Vol <b>{(!volumeAvailable||current.Volume==null||!Number.isFinite(Number(current.Volume))||Number(current.Volume)<=0?'—':Number(current.Volume).toLocaleString('en-IN',{notation:'compact',maximumFractionDigits:1}))}</b></span><span className="ohlcTime">{label(current.time)}</span></div><svg className="tradingSvg" viewBox={`0 0 ${W} ${H}`} role="img" aria-label="OHLC candlestick price chart with volume bars" onMouseLeave={()=>setHover(null)} onMouseMove={e=>{const rect=e.currentTarget.getBoundingClientRect();const px=(e.clientX-rect.left)/rect.width*W;const i=Math.max(0,Math.min(valid.length-1,Math.floor((px-left)/(W-left-right)*valid.length)));setHover(i);}}>{Array.from({length:6},(_,i)=>{const v=hi-(hi-lo)*i/5;const yy=y(v);return <g key={i}><line x1={left} x2={W-right} y1={yy} y2={yy} stroke={colors.grid} strokeDasharray="3 5"/><text x={left-10} y={yy+4} textAnchor="end" fill={colors.text} fontSize="12">{v.toLocaleString('en-IN',{maximumFractionDigits:0})}</text></g>})}{chartType==='candles'&&valid.map((b,i)=>{const cx=x(i),up=b.Close>=b.Open,col=up?colors.green:colors.red,openY=y(b.Open),closeY=y(b.Close);const volH=(Number(b.Volume)||0)/volMax*54;return <g key={`${b.time}-${i}`}><line x1={cx} x2={cx} y1={y(b.High)} y2={y(b.Low)} stroke={col} strokeWidth={1.4}/><rect x={cx-bodyW/2} y={Math.min(openY,closeY)} width={bodyW} height={Math.max(1.5,Math.abs(closeY-openY))} fill={col} stroke={col}/><rect x={cx-bodyW/2} y={volBottom-volH} width={bodyW} height={volH} fill={col} opacity={.55}/></g>})}{chartType==='line'&&<path d={closePath} fill="none" stroke={colors.blue} strokeWidth="2" vectorEffect="non-scaling-stroke"/>}{indicators.includes('SMA 20')&&<path d={pathFor(sma20)} fill="none" stroke="#f59e0b" strokeWidth="1.8" vectorEffect="non-scaling-stroke"/>}{indicators.includes('SMA 50')&&<path d={pathFor(sma50)} fill="none" stroke="#8b5cf6" strokeWidth="1.8" vectorEffect="non-scaling-stroke"/>}{indicators.includes('EMA 20')&&<path d={pathFor(ema20)} fill="none" stroke="#06b6d4" strokeWidth="1.6" vectorEffect="non-scaling-stroke"/>}{indicators.includes('Bollinger Bands')&&<><path d={pathFor(bb.map(v=>v?.upper??null))} fill="none" stroke="#94a3b8" strokeWidth="1.2" strokeDasharray="4 3"/><path d={pathFor(bb.map(v=>v?.lower??null))} fill="none" stroke="#94a3b8" strokeWidth="1.2" strokeDasharray="4 3"/></>}{[0,Math.floor((valid.length-1)/3),Math.floor(2*(valid.length-1)/3),valid.length-1].filter((v,i,a)=>a.indexOf(v)===i).map(i=><text key={i} x={x(i)} y={priceBottom+22} textAnchor="middle" fill={colors.text} fontSize={11}>{label(valid[i].time)}</text>)}<line x1={left} x2={W-right} y1={priceBottom+34} y2={priceBottom+34} stroke={colors.grid}/><text x={left} y={H-10} fill={colors.text} fontSize={11}>{volumeAvailable?'VOLUME':'VOLUME · unavailable from provider'}</text>{hover!==null&&<g><line x1={x(hover)} x2={x(hover)} y1={top} y2={volBottom} stroke={colors.text} strokeDasharray="4 4"/><line x1={left} x2={W-right} y1={y(valid[hover].Close)} y2={y(valid[hover].Close)} stroke={colors.text} strokeDasharray="4 4"/></g>}</svg><div className="chartLegend"><span><i style={{background:colors.green}}/> Bullish candle</span><span><i style={{background:colors.red}}/> Bearish candle</span><span><i style={{background:colors.blue}}/> Price scale</span><small>Move your pointer over the chart to inspect OHLC values. Latest candle may still be forming. Missing provider volume is shown as —, not fabricated as zero.</small></div></div>;
}

