function heatmapTileStyle(change:number|null|undefined, theme:'dark'|'light'):React.CSSProperties {
 if(change==null || !Number.isFinite(change)) return {background:theme==='light'?'#f1f5f9':'#182437',borderColor:theme==='light'?'#dbe3ed':'#2b3b52'};
 const intensity=Math.min(0.48,0.12+Math.abs(change)*0.075);
 return change>=0 ? {background:`rgba(16,185,129,${intensity})`,borderColor:`rgba(16,185,129,${Math.min(.85,intensity+0.25)})`} : {background:`rgba(244,63,94,${intensity})`,borderColor:`rgba(244,63,94,${Math.min(.85,intensity+0.25)})`};
}
